<script setup lang="ts">import{computed,reactive,ref}from'vue';import{solveRectangularPlate,type RectangularPlateBoundary,type RectangularPlateResult}from'../../../core/plate-shell';import{evaluateNumericExpression}from'../../../core/numeric';import{convertPresetValue,getPresetUnit,getUnitDefinition,normalizeToSI,type QuantityId,type UnitPresetId}from'../../../core/units';import RectangularPlateDiagram from'./RectangularPlateDiagram.vue';import RectangularPlateResults from'./RectangularPlateResults.vue';type F='a'|'b'|'t'|'x'|'y'|'e'|'nu'|'q'|'n';interface D extends Record<F,string>{boundary:RectangularPlateBoundary|null};const DEF:D={boundary:null,a:'1000',b:'1000',t:'20',x:'0',y:'0',e:'200000',nu:'.3',q:'.01',n:'321'};const d=reactive<D>({...DEF}),preset=ref<UnitPresetId>('engineering'),result=ref<RectangularPlateResult|null>(null),error=ref('');const fs:ReadonlyArray<readonly[F,QuantityId]>=[['a','length'],['b','length'],['t','length'],['x','length'],['y','length'],['e','elasticModulus'],['q','pressure']];const units=computed(()=>({l:sym('length'),e:sym('elasticModulus'),q:sym('pressure')}));function sym(q:QuantityId){const id=getPresetUnit(q,preset.value);return getUnitDefinition(q,id).symbol}function invalid(){result.value=null;error.value=''}function sw(n:UnitPresetId){for(const[f,q]of fs)try{const v=evaluateNumericExpression(d[f]),x=convertPresetValue(v,q,preset.value,n);if(x!==null)d[f]=String(Number(x.toPrecision(12)))}catch{}preset.value=n}function p(f:F){return evaluateNumericExpression(d[f])}function si(f:F,q:QuantityId){return normalizeToSI(p(f),q,getPresetUnit(q,preset.value))}function calc(){invalid();try{if(!d.boundary)throw new Error('必须显式选择矩形板边界');result.value=solveRectangularPlate({calculatorId:'rectangular-plate',boundary:d.boundary,lengthXM:si('a','length'),lengthYM:si('b','length'),thicknessM:si('t','length'),evaluationXM:si('x','length'),evaluationYM:si('y','length'),material:{elasticModulusPa:si('e','elasticModulus'),poissonRatio:p('nu')},pressurePa:si('q','pressure'),maxOddIndex:Math.trunc(p('n')),ritzMaxOrder:8})}catch(e){error.value=e instanceof Error?e.message:'计算失败'}}function reset(){Object.assign(d,DEF);preset.value='engineering';invalid()}</script><template><section class="calculator"><header><div><p>P3 · Gate P3-3</p><h2>矩形薄板弯曲</h2><span>中心坐标；均布载荷；SSSS Navier / CCCC 里茨。</span></div><div class="units"><button :class="{active:preset==='engineering'}" :aria-pressed="preset==='engineering'" @click="sw('engineering')">t–mm–s–N–MPa</button><button :class="{active:preset==='si'}" :aria-pressed="preset==='si'" @click="sw('si')">SI（kg–m–s–N–Pa）</button></div></header><div class="layout"><form @submit.prevent="calc"><fieldset><legend>1. 边界（必选）</legend><label><input v-model="d.boundary" type="radio" value="ssss" @change="invalid">四边简支 SSSS</label><label><input v-model="d.boundary" type="radio" value="cccc" @change="invalid">四边固支 CCCC</label></fieldset><h3>2. 几何</h3><label v-for="f in [['a','长度 a'],['b','宽度 b'],['t','厚度 t'],['x','求值 x'],['y','求值 y']]" :key="f[0]">{{f[1]}}<div><input v-model="d[f[0] as F]" :aria-label="`矩形板${f[1]}`" @input="invalid"><b>{{units.l}}</b></div></label><h3>3. 材料</h3><label>弹性模量 E<div><input v-model="d.e" aria-label="矩形板弹性模量" @input="invalid"><b>{{units.e}}</b></div></label><label>泊松比 ν<div><input v-model="d.nu" aria-label="矩形板泊松比" @input="invalid"><b>—</b></div></label><h3>4. 载荷与级数</h3><label>均布压力 q<div><input v-model="d.q" aria-label="矩形板均布压力" @input="invalid"><b>{{units.q}}</b></div></label><label v-if="d.boundary!=='cccc'">最高奇数索引<div><input v-model="d.n" aria-label="Navier 最高奇数索引" @input="invalid"><b>≤321</b></div></label><section><button>计算矩形板</button><button type="button" @click="reset">重置</button></section></form><RectangularPlateDiagram :boundary="d.boundary"/></div><div v-if="error" role="alert" class="error">{{error}}</div><RectangularPlateResults v-if="result" :result="result" :unit-preset="preset"/></section></template><style scoped>.calculator{display:grid;gap:18px}.calculator>header{display:flex;justify-content:space-between;padding:20px;border:1px solid var(--color-line);border-left:4px solid var(--color-brand);border-radius:12px;background:#f7faf9}header p{margin:0;color:var(--color-brand);font-size:10px}h2{margin:4px 0}.units{display:flex;gap:5px}.units button,form section button{padding:9px;border:1px solid var(--color-line);border-radius:8px;background:#fff}.units .active,form section button:first-child{color:#fff;background:var(--color-brand)}.layout{display:grid;grid-template-columns:1.2fr .8fr;gap:18px;align-items:start}form{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;padding:20px;border:1px solid var(--color-line);border-radius:var(--radius-large);background:#fff}fieldset,h3,form section{grid-column:1/-1}fieldset{display:flex;gap:20px}label{display:grid;gap:5px;font-size:12px}label>div{display:grid;grid-template-columns:1fr auto;border:1px solid #cad5da;border-radius:8px;overflow:hidden}input{min-width:0;padding:10px;border:0}b{padding:10px;background:#f7f9fa;font-size:10px}form section{display:flex;gap:8px}.error{padding:14px;color:#8f342d;background:#fff0ed}@media(max-width:900px){.calculator>header{flex-direction:column}.units{flex-direction:column}.layout{grid-template-columns:1fr}}@media(max-width:560px){form{grid-template-columns:1fr}fieldset,h3,form section{grid-column:auto}fieldset,form section{flex-direction:column}}</style>
